ItemData AmmoPack 
{ description = "Ammo Pack"; shapeFile = "AmmoPack"; className = "Backpack"; heading = "cBackpacks"; imageType = AmmoPackImage; shadowDetailMask = 4; mass = 2.0; elasticity = 0.2; price = 325; hudIcon = "ammopack"; showWeaponBar = true; hiliteOnActive = true; }; function AmmoPack::onDrop(%player, %item) { if($matchStarted) { %item = Item::onDrop(%player,%item); for(%i = 0; %i < 13 ; %i = %i +1) { %numPack = 0; %ammoItem = $AmmoPackItems[%i]; %maxnum = $ItemMax[Player::getArmor(%player), %ammoItem]; %pCount = Player::getItemCount(%player, %ammoItem); if(%pCount > %maxnum) { %numPack = %pCount - %maxnum; Player::decItemCount(%player,%ammoItem,%numPack); } if(%i == 0) { %item.BulletAmmo = %numPack; } else if(%i == 1) { %item.PlasmaAmmo = %numPack; } else if(%i == 2) { %item.DiscAmmo = %numPack; } else if(%i == 3) { %item.GrenadeAmmo = %numPack; } else if(%i == 4) { %item.Grenade = %numPack; } else if(%i == 5) { %item.MortarAmmo = %numPack; } else if(%i == 6) { %item.RocketAmmo = %numPack; } else if(%i == 7) { %item.SniperAmmo = %numPack; } else if(%i == 8) { %item.RailAmmo = %numPack; } else if(%i == 9) { %item.SilencerAmmo = %numPack; } else if(%i == 10) { %item.VulcanAmmo = %numPack; } else if(%i == 11) { %item.Beacon = %numPack; } else if(%i == 12) { %item.TranqAmmo = %numPack; } else { %item.MineAmmo = %numPack; } } } } function AmmoPack::onCollision(%this,%object) { if (getObjectType(%object) == "Player") { %item = Item::getItemData(%this); %count = Player::getItemCount(%object,%item); if (Item::giveItem(%object,%item,Item::getCount(%this))) { Item::playPickupSound(%this); checkPacksAmmo(%object, %this); Item::respawn(%this); } } } function checkPacksAmmo(%player, %item) { for(%i = 0; %i < 13 ; %i = %i +1) { %ammoItem = $AmmoPackItems[%i]; if(%i == 0) { %numAdd = %item.BulletAmmo; } else if(%i == 1) { %numAdd = %item.PlasmaAmmo; } else if(%i == 2) { %numAdd = %item.DiscAmmo; } else if(%i == 3) { %numAdd = %item.GrenadeAmmo; } else if(%i == 4) { %numAdd = %item.Grenade; } else if(%i == 5) { %numAdd = %item.MortarAmmo; } else if(%i == 6) { %numAdd = %item.RocketAmmo; } else if(%i == 7) { %numAdd = %item.SniperAmmo; } else if(%i == 8) { %numAdd = %item.RailAmmo; } else if(%i == 9) { %numAdd = %item.SilencerAmmo; } else if(%i == 10) { %numAdd = %item.VulcanAmmo; } else if(%i == 11) { %numAdd = %item.Beacon; } else if(%i == 12) { %numAdd = %item.TranqAmmo; } else { %numAdd = %item.MineAmmo; } Player::incItemCount(%player,%ammoItem,%numAdd); } } function fillAmmoPack(%client) { %player = Client::getOwnedObject(%client); for(%i = 0; %i < 13 ; %i = %i +1) { %item = $AmmoPackItems[%i]; %maxnum = $AmmoPackMax[%item]; %maxnum = checkResources(%player,%item,%maxnum); if(%maxnum) { Player::incItemCount(%client,%item,%maxnum); teamEnergyBuySell(%player,%item.price * %maxnum * -1); } } } 




